def build_train_transform(config):
    """Complementary Stochastic Augmentation with Adaptive Erasing.
    Routes each image through one of three augmentation paths with
    complementary properties: TrivialAugmentWide (diverse single-op),
    RandAugment (consistent multi-op), or identity (preserving originals).
    Dataset-adaptive random erasing provides spatial regularization."""
    import random
    class ComplementaryAugRouter:
        def __init__(self, dataset):
            self.trivial = transforms.TrivialAugmentWide()
            self.rand = transforms.RandAugment(num_ops=2, magnitude=9)
            if dataset == 'cifar100':
                self.weights = [0.5, 0.4, 0.1]  # more augmentation for harder task
            else:
                self.weights = [0.6, 0.3, 0.1]  # lighter for easier tasks
        def __call__(self, img):
            r = random.random()
            if r < self.weights[0]:
                return self.trivial(img)
            elif r < self.weights[0] + self.weights[1]:
                return self.rand(img)
            return img  # identity path preserves some originals
    ds = config['dataset']
    erase_p = 0.5 if ds == 'cifar100' else 0.25
    return transforms.Compose([
        ComplementaryAugRouter(ds),
        transforms.RandomCrop(config['img_size'], padding=4),
        transforms.RandomHorizontalFlip(),
        transforms.ToTensor(),
        transforms.RandomErasing(p=erase_p, scale=(0.02, 0.2), ratio=(0.3, 3.3)),
        transforms.Normalize(config['mean'], config['std']),
    ])
